starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "bucket_name" {
  description = "Input variable bucket_name."
  type        = string
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_kms_key" "this" {
  description         = "Arena managed key"
  enable_key_rotation = true
}

resource "aws_kms_alias" "this" {
  name          = "alias/arena-key"
  target_key_id = aws_kms_key.this.id
}

resource "aws_s3_bucket" "this" {
  bucket = "app-assets"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  # TODO - Complete the aws_s3_bucket_server_side_encryption_configuration resource.
  # Add the arguments and nested blocks required for aws_s3_bucket_server_side_encryption_configuration.
}

starter.outputs.tf:
output "key_arn" {
  value = aws_kms_key.this.arn
}

output "bucket_id" {
  value = aws_s3_bucket.this.id
}
